methods.body:
this.frame = (this.frame + 1) % 65536
this.thrustHeld = c.thrust
const f = this.draft()
if (!this.playing && c.start) { this.begin(f); this.commit(f); return }
this.upkeep(f)
if (this.mode != "scores") {
    if (!this.playing || this.sinceStart >= 128) {        // ship and saucer wake on the last frame of "PLAYER 1"
        this.fire(f, c)
        this.hyperspace(f, c)
        this.flyShip(f, c)
        this.runSaucer(f)
        }
    this.moveAll(f)
    this.findHits(f)
    }
this.playSounds(f)
this.random()
if (this.nextWaveIn > 0) this.nextWaveIn = this.nextWaveIn - 1
else if (this.rocksLeft(f) == 0) this.newWave(f)
this.commit(f)

if (!this.playing) return
this.sinceStart = this.sinceStart + 1
if (this.sinceStart <= 128) return
if (this.frame % 64 == 0 && this.beatGap != 8) this.beatGap = this.beatGap - 1
if (f.ship.state == "waiting" && f.ship.wait == 16) {
    if (this.shipsLeft > 0) this.saucerLeaves(f)
    else {
        this.playing = false
        this.frame = 65280 + this.frame % 256         // the high scores wait until the clock comes round
        this.silence()
        }
    }

const near = (a, b) => (Math.floor(a / 256) - Math.floor(b / 256) + 260) % 256 < 8
const things = [f.saucer, ...f.rocks].filter((o) => o.inPlay)
return !things.some((o) => near(o.x, f.ship.x) && near(o.y, f.ship.y))

if (this.frame % 2 == 1) return
this.thrustSound = c.thrust
if (c.thrust) {
    ship.vx = this.limit(ship.vx + 2 * this.cosine(ship.heading))
    ship.vy = this.limit(ship.vy + 2 * this.sine(ship.heading))
    }
else {
    if (ship.vx != 0) ship.vx = ship.vx - 2 * (ship.vx >> 8) - (ship.vx >= 0 ? 1 : 0)
    if (ship.vy != 0) ship.vy = ship.vy - 2 * (ship.vy >> 8) - (ship.vy >= 0 ? 1 : 0)
    }

for (const s of [...f.shots, ...f.saucerShots]) {
    if (!s.inPlay) continue
    this.move(s)
    s.drawn = true
    if (this.frame % 4 == 0) s.life = s.life - 1
    if (s.life == 0) s.inPlay = false
    }
const saucer = f.saucer
if (saucer.inPlay && saucer.blast > 0) this.burnSaucer(f)
else if (saucer.inPlay && (saucer.x + saucer.vx < 0 || saucer.x + saucer.vx >= 8192)) this.saucerLeaves(f)
else if (saucer.inPlay) this.move(saucer)
const ship = f.ship
if (ship.state == "exploding") this.burnShip(f)
else if (ship.state == "flying") {
    ship.x = wrap(ship.x + (ship.vx >> 8), 8192)
    ship.y = wrap(ship.y + (ship.vy >> 8), 6144)
    }
let cleared = false
for (const r of f.rocks) {
    if (!r.inPlay) continue
    if (r.blast == 0) this.move(r)
    else r.blast = this.burn(r.blast)
    if (r.blast >= 256) { r.inPlay = false; r.blast = 0; cleared = true }
    else r.drawn = true
    }
if (cleared && this.rocksLeft(f) == 0) this.nextWaveIn = 127

const d = this.debris.slice()
if (blast < 162) for (let k = 0; k < 12; k++) d[k] = (this.debrisSpeeds[k] >> 4) * 256 + (d[k] & 255)
for (let p = (255 - blast) >> 4; p >= 0; p--) {
    d[2 * p] = d[2 * p] + this.debrisSpeeds[2 * p]
    d[2 * p + 1] = d[2 * p + 1] + this.debrisSpeeds[2 * p + 1]
    }
this.debris = d

for (const s of f.shots) if (s.inPlay && this.strikes(f, s, "shot")) s.inPlay = false
for (const s of f.saucerShots) if (s.inPlay && this.strikes(f, s, "saucer shot")) s.inPlay = false
if (f.saucer.inPlay && f.saucer.blast == 0 && this.strikes(f, f.saucer, "saucer")) this.explode(f.saucer)
if (f.ship.state == "flying" && this.strikes(f, f.ship, "ship")) this.wreckShip(f, true)

const reach = by == "ship" ? 28 : by == "saucer" ? (f.saucer.size == "small" ? 19 : 37) : 0
const saucer = f.saucer
if (by == "shot" && saucer.inPlay && saucer.blast == 0
    && this.touching(hitter, saucer, (saucer.size == "small" ? 42 : 72) + reach)) {
    this.saucerHit(f)
    return true
    }
if (by != "ship" && f.ship.state == "flying" && this.touching(hitter, f.ship, 42 + reach)) {
    this.wreckShip(f, true)
    if (by == "saucer") this.saucerHit(f)       // they collide: the player scores it
    else this.boom("mid", 63)
    return true
    }
for (const r of f.rocks) {
    const box = (r.size == "small" ? 42 : r.size == "medium" ? 72 : 132) + reach
    if (!r.inPlay || r.blast > 0 || !this.touching(hitter, r, box)) continue
    this.rockHit(f, r, by == "shot" || by == "ship")
    return true
    }
return false

this.saucerHoldback = 80
if (this.playing && scores) this.award(rock.size == "large" ? 20 : rock.size == "medium" ? 50 : 100)
const smaller = rock.size == "large" ? "medium" : "small"
let from = 0
for (let k = 0; k < 2 && rock.size != "small"; k++) {
    const i = f.rocks.findIndex((r, j) => j >= from && !r.inPlay)
    if (i < 0) break
    const child = f.rocks[i]
    child.inPlay = true
    child.size = smaller
    child.shape = (this.random() >> 3) % 4
    child.x = rock.x; child.y = rock.y
    child.blast = 0; child.drawn = false; child.struck = false
    this.nudge(child, rock.vx, rock.vy)
    if (k == 0) child.x = child.x ^ ((child.vx & 31) * 2)
    else child.y = child.y ^ ((child.vy & 31) * 2)
    from = i + 1
    }
this.boom(rock.size == "large" ? "low" : rock.size == "medium" ? "mid" : "high", 63)
this.explode(rock)

const before = this.score
this.score = (this.score + points) % 100000
if (Math.floor(this.score / 10000) != Math.floor(before / 10000)) {
    this.shipsLeft = this.shipsLeft + 1
    this.extraShipTone = 176
    }

if (this.extraShipTone > 0) this.extraShipTone = Math.max(0, this.extraShipTone - 2)
if (!this.playing) return
this.saucerShotSound = this.countdown(this.saucerShotSound)
this.shotSound = this.countdown(this.shotSound)
if (f.ship.state != "flying") this.thrustSound = false
if (this.rocksLeft(f) == 0 || f.ship.state == "exploding" || f.ship.state == "waiting") this.rest()
else if (this.beatOn > 0) {
    this.beatOn = this.beatOn - 1
    if (this.beatOn == 0) this.rest()
    }
else {
    this.beatOff = (this.beatOff + 255) % 256
    if (this.beatOff == 0) { this.beatOn = 4; this.beating = true; this.beatHigh = !this.beatHigh }
    }
if (this.boomCount > 0) this.boomCount = this.boomCount - 1

if (!b.on) return b.pending ? { on: true, left: 16, pending: false } : b
if (b.left == 0 || b.pending) return { on: false, left: b.left, pending: b.pending }
return { on: b.left > 1, left: b.left - 1, pending: false }

return Array.from({ length: Math.min(6, ((255 - blast) >> 4) + 1) }, (_, p) => {
    const x = debris[2 * p] >> 8, y = debris[2 * p + 1] >> 8
    return [x, y, x + this.pieces[2 * p], y + this.pieces[2 * p + 1]]
    })

            // each letter's strokes, moved to its place
return Array.from(s).flatMap((c, i) =>
    this.glyphs[this.letters.indexOf(c)].map((g) => g.map((v, k) => k % 2 == 0 ? v + 12 * i : v)))

// a late frame stands for the display frames it covered, and stays out of the average
if (this.frameTime == 0) this.frameTime = dt
else if (dt < 1.5 * this.frameTime) this.frameTime = 0.95 * this.frameTime + 0.05 * dt
const per = Math.max(1, Math.round(0.016 / this.frameTime))
if (Math.abs(per * this.frameTime - 0.016) <= 0.05 * 0.016) {
    this.shown = this.shown + Math.max(1, Math.round(dt / this.frameTime))
    const n = Math.floor(this.shown / per)
    this.shown = this.shown - n * per
    return n
    }
this.banked = this.banked + dt
const n = Math.floor(this.banked / 0.016)
this.banked = this.banked - n * 0.016
return n
